"""
100+ Plain-language glossary terms with grade-8 reading level explanations and examples.
Used for inline hover/tap tooltips across the SkillPath UI.
"""

GLOSSARY_DATA = [
    # --- GENERAL PROGRAMMING & BASICS ---
    {"term": "Algorithm", "category": "General", "plain_meaning": "A step-by-step recipe that a computer follows to solve a problem or finish a task.", "example": "A recipe for baking a cake or steps for sorting names alphabetically."},
    {"term": "API (Application Programming Interface)", "category": "General", "plain_meaning": "A digital messenger that lets two different software applications talk and share information with each other.", "example": "A weather app using a weather service's API to show today's forecast."},
    {"term": "Array / List", "category": "General", "plain_meaning": "An ordered box or container in code that holds multiple items of information together in a single row.", "example": "['apple', 'banana', 'orange']"},
    {"term": "Bug", "category": "General", "plain_meaning": "A mistake or unintended flaw in computer code that makes a program crash or behave strangely.", "example": "A shopping cart saying your total is -10 dollars."},
    {"term": "Boolean", "category": "General", "plain_meaning": "A basic data type that can only ever have one of two answers: True or False.", "example": "is_logged_in = True"},
    {"term": "CLI (Command Line Interface)", "category": "General", "plain_meaning": "A text-only window where you type direct keyboard commands to control your computer without using a mouse.", "example": "Typing 'mkdir my_project' to make a new folder."},
    {"term": "Data Structure", "category": "General", "plain_meaning": "A specific organized way of storing and organizing data in a computer so it can be used efficiently.", "example": "Lists, dictionaries, trees, and queues."},
    {"term": "Debugging", "category": "General", "plain_meaning": "The detective process of finding and fixing mistakes or errors inside your code.", "example": "Checking which line of code caused a calculation to give the wrong number."},
    {"term": "Function", "category": "General", "plain_meaning": "A reusable block of code that takes some input, performs an action, and returns a result.", "example": "A calculate_discount(price, pct) function you can call whenever a sale happens."},
    {"term": "IDE (Integrated Development Environment)", "category": "General", "plain_meaning": "A software program where developers write, test, and debug code, equipped with color highlighting and autocompletion.", "example": "Visual Studio Code or PyCharm."},
    {"term": "JSON (JavaScript Object Notation)", "category": "General", "plain_meaning": "A simple, human-readable text format used all over the web to send structured data back and forth.", "example": "{\"name\": \"Arif\", \"year\": 3}"},
    {"term": "Library / Package", "category": "General", "plain_meaning": "A collection of pre-written code created by other developers that you can plug into your project so you don't have to reinvent the wheel.", "example": "Using Python's math library instead of calculating square roots by hand."},
    {"term": "Loop", "category": "General", "plain_meaning": "A command that tells the computer to repeat a block of code multiple times until a condition is met.", "example": "Sending an email to every customer in a list of 100 people."},
    {"term": "Open Source", "category": "General", "plain_meaning": "Software whose original code is made freely available for anyone in the world to view, use, modify, and improve.", "example": "Linux, Python, and React are open-source."},
    {"term": "Recursion", "category": "General", "plain_meaning": "A programming technique where a function calls itself to solve smaller versions of the exact same problem.", "example": "Opening Russian nesting dolls until you reach the smallest one."},
    {"term": "Refactoring", "category": "General", "plain_meaning": "Cleaning up and rewriting existing code to make it neater and faster without changing what it actually does on the outside.", "example": "Replacing a messy 50-line function with 3 clear 5-line helper functions."},
    {"term": "Syntax", "category": "General", "plain_meaning": "The grammar and spelling rules of a programming language that you must follow so the computer understands you.", "example": "Putting a colon at the end of an if-statement in Python."},
    {"term": "Tech Stack", "category": "General", "plain_meaning": "The complete bundle of programming languages, frameworks, databases, and tools used together to build an application.", "example": "SkillPath uses FastAPI, SQLite, React, and Tailwind CSS."},
    {"term": "Variable", "category": "General", "plain_meaning": "A labeled storage box in computer memory that holds a piece of information that can change over time.", "example": "score = 100"},
    {"term": "Version Control", "category": "General", "plain_meaning": "A software system that records all changes made to files over time so you can recall specific versions or undo mistakes later.", "example": "Git."},

    # --- ARTIFICIAL INTELLIGENCE & MACHINE LEARNING ---
    {"term": "Artificial Intelligence (AI)", "category": "AI", "plain_meaning": "Computer systems designed to perform tasks that typically require human intelligence, such as recognizing speech, analyzing patterns, or making recommendations.", "example": "A recommendation system suggesting videos you might like."},
    {"term": "Machine Learning (ML)", "category": "AI", "plain_meaning": "A subset of AI where computers learn from patterns in historical examples rather than following hardcoded if-then rules.", "example": "Teaching a computer to recognize cats by showing it 10,000 cat photos."},
    {"term": "Deep Learning", "category": "AI", "plain_meaning": "A type of machine learning using multi-layered artificial neural networks capable of learning complex representations from vast datasets.", "example": "Self-driving cars detecting pedestrians in real time."},
    {"term": "Neural Network", "category": "AI", "plain_meaning": "A computing system inspired by the human brain made of interconnected mathematical nodes (neurons) that pass signals to each other.", "example": "A network that detects handwriting on postal envelopes."},
    {"term": "Supervised Learning", "category": "AI", "plain_meaning": "Training a machine learning model using data where the correct answers (labels) are already provided.", "example": "Showing the computer house sizes and their real sold prices so it can predict future prices."},
    {"term": "Unsupervised Learning", "category": "AI", "plain_meaning": "Giving a model raw data with no labels and letting it discover hidden clusters or groupings on its own.", "example": "Grouping online store customers into 4 distinct shopping personality types."},
    {"term": "Overfitting", "category": "AI", "plain_meaning": "When an AI model memorizes its training data so rigidly that it fails to perform well on new, unseen real-world data.", "example": "A student memorizing practice test answers word-for-word but failing the real exam when questions change."},
    {"term": "Underfitting", "category": "AI", "plain_meaning": "When an AI model is too simple to capture the underlying pattern in data, leading to poor predictions everywhere.", "example": "Trying to draw a straight line through data that clearly curves."},
    {"term": "Hyperparameters", "category": "AI", "plain_meaning": "External settings chosen by the human engineer before training begins that control how the algorithm learns.", "example": "Setting the learning rate speed or tree depth before training a Random Forest."},
    {"term": "Weights & Biases", "category": "AI", "plain_meaning": "The adjustable internal numbers inside a neural network that get tuned during training to reduce prediction errors.", "example": "Turning internal mathematical dials until predictions match actual outputs."},
    {"term": "Backpropagation", "category": "AI", "plain_meaning": "The mathematical algorithm that calculates how much each weight contributed to an error and guides how to adjust them.", "example": "Tracing an error backwards through a network to see where the prediction went wrong."},
    {"term": "Loss Function", "category": "AI", "plain_meaning": "A mathematical formula that measures the difference between what the model predicted and what actually happened.", "example": "Calculating how many inches off a target arrow landed."},
    {"term": "Epoch", "category": "AI", "plain_meaning": "One complete pass where the machine learning algorithm has seen and trained on every single example in the training dataset.", "example": "Reading through an entire textbook once from cover to cover."},
    {"term": "Token", "category": "AI", "plain_meaning": "A piece of a word or sentence that a Large Language Model reads and processes as a single unit.", "example": "The word 'SkillPath' might be broken into two tokens: 'Skill' and 'Path'."},
    {"term": "Prompt Engineering", "category": "AI", "plain_meaning": "The practice of carefully wording questions, instructions, and examples given to an AI model to get the most accurate and useful reply.", "example": "Adding 'Explain in simple terms for a 12-year-old in 3 bullet points' to a question."},
    {"term": "LLM (Large Language Model)", "category": "AI", "plain_meaning": "A massive deep learning model trained on vast amounts of text that can understand, generate, and translate human language.", "example": "Google Gemini or GPT-4."},
    {"term": "Embeddings", "category": "AI", "plain_meaning": "Converting words, sentences, or images into long lists of numbers (vectors) where concepts with similar meanings are close together in space.", "example": "'King' and 'Queen' will have embedding numbers that sit very close together."},
    {"term": "Vector Database", "category": "AI", "plain_meaning": "A specialized database designed to store and search billions of embedding numbers at high speed based on conceptual similarity.", "example": "FAISS, Chroma, or Pinecone."},
    {"term": "RAG (Retrieval-Augmented Generation)", "category": "AI", "plain_meaning": "Fetching reliable facts from a database first and handing them to an LLM so it answers accurately without hallucinating or making up facts.", "example": "SkillPath fetching real course URLs from its database before the AI Mentor recommends them."},
    {"term": "Hallucination", "category": "AI", "plain_meaning": "When an AI model confidently generates an answer that sounds convincing but is completely made up or factually incorrect.", "example": "An LLM inventing a fake book title and author that do not exist."},
    {"term": "Transformer", "category": "AI", "plain_meaning": "A modern neural network architecture that uses self-attention to process all words in a sentence at the same time rather than one by one.", "example": "The underlying architecture that powers modern LLMs like Gemini."},
    {"term": "Fine-Tuning", "category": "AI", "plain_meaning": "Taking an existing pre-trained AI model and giving it a small set of specialized examples to teach it a specific new skill or tone.", "example": "Teaching a general language model how to write medical prescription summaries."},
    {"term": "MLOps", "category": "AI", "plain_meaning": "The operational practices and automation tools used to reliably deploy, monitor, and maintain machine learning models in production.", "example": "Setting up an alert if an AI model starts making inaccurate predictions in production."},

    # --- DATA & ANALYTICS ---
    {"term": "CSV (Comma-Separated Values)", "category": "Data", "plain_meaning": "A plain text file where spreadsheet rows are stored on separate lines, with columns separated by simple commas.", "example": "id,name,score\\n1,Arif,92"},
    {"term": "DataFrame", "category": "Data", "plain_meaning": "A 2-dimensional table of data with rows and named columns, like an Excel sheet loaded into computer memory.", "example": "A Pandas DataFrame of 5,000 customer orders."},
    {"term": "Correlation", "category": "Data", "plain_meaning": "A statistical number between -1 and +1 indicating how closely two things move together.", "example": "Study hours and exam marks often have a positive correlation."},
    {"term": "Outlier", "category": "Data", "plain_meaning": "A data point that differs dramatically from the rest of the observations in a dataset.", "example": "A house listed for $50,000,000 in a neighborhood where all other houses cost $300,000."},
    {"term": "A/B Testing", "category": "Data", "plain_meaning": "A scientific method comparing two versions of a webpage or app feature to see which one performs better for real users.", "example": "Showing 50% of users a green button and 50% a blue button to see which gets more clicks."},
    {"term": "Normalization", "category": "Data", "plain_meaning": "Rescaling numbers in a dataset so they all fall into a standard range, like between 0 and 1.", "example": "Converting salaries ($50k-$200k) and ages (18-80) to a shared 0-1 scale so math formulas treat them fairly."},
    {"term": "Imputation", "category": "Data", "plain_meaning": "The process of filling in missing values in a dataset with educated guesses, such as the median or average value.", "example": "Replacing missing age values with the average age of all users."},
    {"term": "Cohort Analysis", "category": "Data", "plain_meaning": "Grouping users based on a shared characteristic (like signup month) to track how their behavior changes over time.", "example": "Seeing how many students who joined in September are still studying in December."},
    {"term": "KPI (Key Performance Indicator)", "category": "Data", "plain_meaning": "A measurable metric that indicates how effectively an organization or project is achieving key objectives.", "example": "Percentage of students who land an internship within 6 months of graduation."},
    {"term": "ETL (Extract, Transform, Load)", "category": "Data", "plain_meaning": "The process of pulling raw data from different sources, cleaning it, and loading it into a central database for analysis.", "example": "Pulling sales data from 10 store computers every night and loading it into a company warehouse."},
    {"term": "Data Warehouse", "category": "Data", "plain_meaning": "A large, centralized database specifically designed to store historical business data for fast reporting and analysis.", "example": "Snowflake or Google BigQuery."},
    {"term": "Relational Database", "category": "Data", "plain_meaning": "A database that stores data in structured tables linked to each other using common ID keys.", "example": "An Orders table linked to a Customers table via customer_id."},
    {"term": "Primary Key", "category": "Data", "plain_meaning": "A special column in a database table containing a unique identifier for every single row.", "example": "Your student roll number or national ID."},
    {"term": "Foreign Key", "category": "Data", "plain_meaning": "A column in one database table that points to the primary key of another table to link them together.", "example": "user_id in the roadmap_items table pointing to users.id."},
    {"term": "SQL JOIN", "category": "Data", "plain_meaning": "A SQL command that combines columns from two or more tables based on a related column between them.", "example": "Combining student names with their exam scores from two separate tables."},

    # --- WEB DEVELOPMENT ---
    {"term": "Frontend", "category": "Web", "plain_meaning": "The client-facing part of an application that runs directly in the user's browser, including buttons, text, and graphics.", "example": "The interactive SkillPath dashboard screen you click on."},
    {"term": "Backend", "category": "Web", "plain_meaning": "The engine room behind the scenes running on remote servers that handles business logic, databases, and authentication.", "example": "The FastAPI server that calculates your job readiness date and stores your account."},
    {"term": "REST (Representational State Transfer)", "category": "Web", "plain_meaning": "A standardized set of rules for building web APIs using standard HTTP methods like GET, POST, PUT, and DELETE.", "example": "POST /auth/login to sign in or GET /roadmap to view your roadmap."},
    {"term": "HTTP Status Code", "category": "Web", "plain_meaning": "A 3-digit number sent by a web server telling the browser whether the request succeeded or what kind of error occurred.", "example": "200 means OK, 404 means Not Found, 500 means Server Error."},
    {"term": "DOM (Document Object Model)", "category": "Web", "plain_meaning": "The live tree structure representing all HTML elements on a webpage that JavaScript can inspect and change dynamically.", "example": "JavaScript adding a new item to a shopping list without reloading the page."},
    {"term": "Component", "category": "Web", "plain_meaning": "A self-contained, reusable piece of code in modern web development that controls its own visual layout and behavior.", "example": "A Navbar component or a SkillCard component."},
    {"term": "State", "category": "Web", "plain_meaning": "The live, changing memory inside a web component that remembers current user choices, like whether a drawer is open.", "example": "is_drawer_open = True"},
    {"term": "Props (Properties)", "category": "Web", "plain_meaning": "Data passed down from a parent component to a child component to customize how it looks or behaves.", "example": "Passing title='AI/ML Engineer' into a CareerCard component."},
    {"term": "Responsive Design", "category": "Web", "plain_meaning": "Designing websites so their layouts and fonts automatically reshape to look clean on mobile phones, tablets, and widescreen monitors.", "example": "A 3-column desktop layout collapsing cleanly into 1 vertical column on a smartphone."},
    {"term": "Cookie", "category": "Web", "plain_meaning": "A small text file saved by your browser on your device to remember who you are when you return to a website.", "example": "Remembering that you are logged into your account so you don't have to re-enter your password."},
    {"term": "CORS (Cross-Origin Resource Sharing)", "category": "Web", "plain_meaning": "A browser security mechanism that controls whether a website running on one domain can request data from a different domain.", "example": "Allowing frontend localhost:5173 to call backend localhost:8000."},
    {"term": "JWT (JSON Web Token)", "category": "Web", "plain_meaning": "A compact, cryptographically signed digital badge that your browser presents to the server to prove you are logged in.", "example": "A signed token verifying that user_id=12 has learner privileges."},
    {"term": "Endpoint", "category": "Web", "plain_meaning": "A specific URL path on a server where an API can be reached to retrieve or send data.", "example": "https://api.skillpath.dev/profile"},
    {"term": "Asynchronous (Async)", "category": "Web", "plain_meaning": "Running a long task in the background without freezing the entire program or locking the user's screen.", "example": "Waiting for a database query to finish while the user can still scroll smoothly."},
    {"term": "Webhook", "category": "Web", "plain_meaning": "An automated notification that one computer system sends to another immediately whenever an event takes place.", "example": "A payment gateway notifying your server the instant a transaction completes."},

    # --- CLOUD, DEVOPS & INFRASTRUCTURE ---
    {"term": "Cloud Computing", "category": "Cloud", "plain_meaning": "Renting computing power, storage, and databases over the internet from companies like Amazon, Google, or Microsoft instead of buying physical computers.", "example": "Storing photos on Google Drive or running code on AWS servers."},
    {"term": "Server", "category": "Cloud", "plain_meaning": "A powerful computer connected to the internet 24 hours a day whose job is to respond to requests from other computers (clients).", "example": "The computer that hosts the SkillPath website and sends pages to your browser."},
    {"term": "Container", "category": "Cloud", "plain_meaning": "A lightweight package containing an application and everything it needs to run, ensuring it behaves identically on any operating system.", "example": "A Docker container running Python and FastAPI."},
    {"term": "Docker", "category": "Cloud", "plain_meaning": "The world's most popular software platform used to build, share, and run applications inside isolated containers.", "example": "Using 'docker run skillpath-backend' to launch the entire server instantly."},
    {"term": "CI/CD", "category": "Cloud", "plain_meaning": "Continuous Integration & Continuous Delivery: automating the testing and shipping of code so updates reach users quickly and safely.", "example": "Every time code is pushed, tests run and the live website updates automatically within 5 minutes."},
    {"term": "Kubernetes", "category": "Cloud", "plain_meaning": "An open-source system originally created by Google to automatically deploy, scale, and manage thousands of containerized applications.", "example": "Spinning up 20 extra web server containers during a massive holiday shopping sale."},
    {"term": "DNS (Domain Name System)", "category": "Cloud", "plain_meaning": "The internet's phonebook that translates human-friendly website names (like skillpath.dev) into computer IP addresses (like 192.0.2.1).", "example": "Typing 'google.com' and reaching the correct server IP address."},
    {"term": "IP Address", "category": "Cloud", "plain_meaning": "A unique string of numbers separated by periods that identifies each computer connected to the internet.", "example": "127.0.0.1 (which means 'this local computer')."},
    {"term": "Load Balancer", "category": "Cloud", "plain_meaning": "A traffic director that evenly distributes incoming web visitors across multiple servers so none gets overloaded.", "example": "Splitting 100,000 visitors evenly across 10 identical servers."},
    {"term": "Virtual Machine (VM)", "category": "Cloud", "plain_meaning": "A digital computer that runs inside physical computer hardware, behaving just like a completely separate machine with its own operating system.", "example": "An Amazon EC2 instance running Ubuntu Linux in the cloud."},
    {"term": "Serverless", "category": "Cloud", "plain_meaning": "A cloud execution model where you simply upload a function, and the cloud provider runs it only when needed without you managing servers.", "example": "AWS Lambda or Google Cloud Functions."},
    {"term": "Microservices", "category": "Cloud", "plain_meaning": "An architectural approach where a big application is broken into many small, independent services that communicate via APIs.", "example": "A separate service for user login, another for payments, and another for notifications."},
    {"term": "Monolith", "category": "Cloud", "plain_meaning": "A software architecture where all components and features of an application are bundled and run together in a single unified codebase.", "example": "A classic web app where frontend, backend, and admin tools live in one project."},

    # --- TESTING & SECURITY ---
    {"term": "Unit Test", "category": "Testing", "plain_meaning": "An automated check verifying that one small, isolated piece of code (like a single function) calculates the correct output.", "example": "Testing if add(2, 2) really returns 4."},
    {"term": "Integration Test", "category": "Testing", "plain_meaning": "A test verifying that multiple separate pieces of code or services work together correctly as a combined unit.", "example": "Testing that the login endpoint can save a user to the database and return a valid JWT."},
    {"term": "End-to-End (E2E) Test", "category": "Testing", "plain_meaning": "A test that simulates a real user's entire journey through an application from start to finish.", "example": "An automated robot opening a browser, filling a form, clicking submit, and checking the confirmation message."},
    {"term": "Encryption", "category": "Testing", "plain_meaning": "Scrambling readable information into secret code so only people with the secret key can unlock and read it.", "example": "HTTPS encrypting your credit card details as they travel across the internet."},
    {"term": "Hashing", "category": "Testing", "plain_meaning": "A one-way mathematical function that turns any text into a fixed-length string that cannot be reversed.", "example": "Storing password hashes or SHA-256 fingerprints on SkillPath Verified Passports."},
    {"term": "SHA-256", "category": "Testing", "plain_meaning": "A cryptographic secure hash algorithm that produces a unique 256-bit (64-character) fingerprint of any data.", "example": "Used by SkillPath to prove that a skill certificate has not been altered or tampered with."},
    {"term": "SQL Injection", "category": "Testing", "plain_meaning": "A security vulnerability where an attacker types malicious database commands into a web form to steal or delete database records.", "example": "Entering '' OR 1=1; -- into a password box to bypass login."},
    {"term": "XSS (Cross-Site Scripting)", "category": "Testing", "plain_meaning": "A security flaw where attackers inject malicious JavaScript into web pages viewed by other innocent users.", "example": "Putting a script tag inside a user comment that steals user session cookies."},
    {"term": "Phishing", "category": "Testing", "plain_meaning": "A cybercrime where attackers pose as legitimate organizations in deceptive emails or messages to trick people into revealing passwords.", "example": "A fake email pretending to be your college bank asking you to reset your password."},
    {"term": "Firewall", "category": "Testing", "plain_meaning": "A security barrier that monitors and filters incoming and outgoing network traffic based on predetermined safety rules.", "example": "Blocking all incoming connections except for port 443 (secure web traffic)."},
    {"term": "Penetration Testing", "category": "Testing", "plain_meaning": "An authorized simulated cyberattack on a computer system performed to identify security weaknesses before real attackers find them.", "example": "Hiring ethical hackers to test if a university portal can be breached."},

    # --- CAREER & INTERVIEW TERMS ---
    {"term": "Portfolio", "category": "General", "plain_meaning": "A curated collection of real projects, code repositories, and case studies that showcase your practical abilities to prospective employers.", "example": "A personal website with links to your live web apps and GitHub repositories."},
    {"term": "Cap-Stone Project", "category": "General", "plain_meaning": "A comprehensive, realistic project completed near the end of a learning path that ties all acquired skills together into one production-grade application.", "example": "Building the complete SkillPath platform."},
    {"term": "Technical Interview", "category": "General", "plain_meaning": "A job interview where employers assess your hands-on coding, problem-solving, and system design abilities.", "example": "Explaining how an algorithm works or answering questions with SkillPath's Mock Interview Coach."},
    {"term": "Behavioral Interview", "category": "General", "plain_meaning": "An interview focused on your past experiences, communication skills, teamwork, and how you handle challenges.", "example": "Answering 'Tell me about a time you faced a difficult deadline.'"},
    {"term": "STAR Method", "category": "General", "plain_meaning": "A structured technique for answering interview questions: Situation, Task, Action, and Result.", "example": "Explaining a project by describing the challenge, your role, your specific actions, and the measurable outcome."},
    {"term": "Peer Review / Code Review", "category": "General", "plain_meaning": "An evaluation where fellow developers inspect your code, provide constructive feedback, and catch mistakes before merging.", "example": "A senior engineer commenting on a GitHub Pull Request suggesting a cleaner way to write a loop."},
    {"term": "Sprint", "category": "General", "plain_meaning": "A focused, short period of time (usually 1 to 2 weeks) during which a team or learner commits to completing a specific set of tasks.", "example": "SkillPath's Weekly Sprint featuring 3 to 5 manageable study tasks."}
]

